local ForgeBellowsValveMaker = {}
local PRODUCTS = {
    iron_forgebellowsvalve = { name = "Železni zaklopka za kovaški meh", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zaklopka za kovaški meh za kovace." },
    bronze_forgebellowsvalve = { name = "Bronast zaklopka za kovaški meh", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zaklopka za kovaški meh za kovace." },
    silver_forgebellowsvalve = { name = "Srebrn zaklopka za kovaški meh", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zaklopka za kovaški meh za kovace." },
    gilded_forgebellowsvalve = { name = "Pozlačen zaklopka za kovaški meh", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zaklopka za kovaški meh za kovace." },
    jewel_set_forgebellowsvalve = { name = "Draguljast zaklopka za kovaški meh", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zaklopka za kovaški meh za kovace." },
    royal_sovereign_forgebellowsvalve = { name = "Kraljevski suveren zaklopka za kovaški meh", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zaklopka za kovaški meh z biseri za krono." },
}
local BUILDINGS = {
    forgebellowsvalve_workshop = { name = "Forgebellowsvalve delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    forgebellowsvalve_house = { name = "Forgebellowsvalve hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_forgebellowsvalve_atelier = { name = "Mojstrski forgebellowsvalve atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_forgebellowsvalve_palace = { name = "Suverena forgebellowsvalve palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeBellowsValveMaker.ironStock=16; ForgeBellowsValveMaker.bronzeStock=12; ForgeBellowsValveMaker.woodStock=12; ForgeBellowsValveMaker.leatherStock=8; ForgeBellowsValveMaker.silverStock=8; ForgeBellowsValveMaker.goldStock=6; ForgeBellowsValveMaker.jewelStock=4; ForgeBellowsValveMaker.pearlStock=4
ForgeBellowsValveMaker.productStock = {}; ForgeBellowsValveMaker.buildings = {}; ForgeBellowsValveMaker.maker = nil; ForgeBellowsValveMaker.activeMaking = {}; ForgeBellowsValveMaker.totalProducts = 0; ForgeBellowsValveMaker.dayTimer = 0
function ForgeBellowsValveMaker.init() ForgeBellowsValveMaker.ironStock=16; ForgeBellowsValveMaker.bronzeStock=12; ForgeBellowsValveMaker.woodStock=12; ForgeBellowsValveMaker.leatherStock=8; ForgeBellowsValveMaker.silverStock=8; ForgeBellowsValveMaker.goldStock=6; ForgeBellowsValveMaker.jewelStock=4; ForgeBellowsValveMaker.pearlStock=4; ForgeBellowsValveMaker.productStock={}; ForgeBellowsValveMaker.buildings={}; ForgeBellowsValveMaker.maker=nil; ForgeBellowsValveMaker.activeMaking={}; ForgeBellowsValveMaker.totalProducts=0; ForgeBellowsValveMaker.dayTimer=0; print("[ForgeBellowsValveMaker] Royal Forge Bellows Valve Maker System initialized (6 products, 4 buildings)") end
function ForgeBellowsValveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeBellowsValveMaker.maker={name=n or ("Zaklopkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopkar najet: %s (spretnost: %d)",ForgeBellowsValveMaker.maker.name,s),"success") end; return true end
function ForgeBellowsValveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeBellowsValveMaker.build(id) local ok,e=ForgeBellowsValveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeBellowsValveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeBellowsValveMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeBellowsValveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeBellowsValveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeBellowsValveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeBellowsValveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeBellowsValveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeBellowsValveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeBellowsValveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeBellowsValveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeBellowsValveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeBellowsValveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeBellowsValveMaker.buildings==0 then return false,"Potrebna zaklopna delavnica" end; if not ForgeBellowsValveMaker.maker then return false,"Potreben zaklopkar" end; return true end
function ForgeBellowsValveMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeBellowsValveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeBellowsValveMaker.ironStock=ForgeBellowsValveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeBellowsValveMaker.bronzeStock=ForgeBellowsValveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeBellowsValveMaker.woodStock=ForgeBellowsValveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeBellowsValveMaker.leatherStock=ForgeBellowsValveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeBellowsValveMaker.silverStock=ForgeBellowsValveMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeBellowsValveMaker.goldStock=ForgeBellowsValveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeBellowsValveMaker.jewelStock=ForgeBellowsValveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeBellowsValveMaker.pearlStock=ForgeBellowsValveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeBellowsValveMaker.maker then t=math.max(1,t-math.floor(ForgeBellowsValveMaker.maker.skill/13)) end; table.insert(ForgeBellowsValveMaker.activeMaking,{id="forgebellowsvalve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeBellowsValveMaker.completeMaking(m) local q=1.0+(ForgeBellowsValveMaker.getQualityBonus()/100); if ForgeBellowsValveMaker.maker then q=q+(ForgeBellowsValveMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeBellowsValveMaker.productStock[m.productType]=(ForgeBellowsValveMaker.productStock[m.productType] or 0)+m.quantity; ForgeBellowsValveMaker.totalProducts=ForgeBellowsValveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeBellowsValveMaker.maker then ForgeBellowsValveMaker.maker.itemsMade=ForgeBellowsValveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeBellowsValveMaker.maker.skill=math.min(100,ForgeBellowsValveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgebellowsvalve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeBellowsValveMaker.update(dt) if not _G.state then return end; ForgeBellowsValveMaker.dayTimer=ForgeBellowsValveMaker.dayTimer+dt; if ForgeBellowsValveMaker.dayTimer>=30 then ForgeBellowsValveMaker.dayTimer=0; for i=#ForgeBellowsValveMaker.activeMaking,1,-1 do local m=ForgeBellowsValveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeBellowsValveMaker.completeMaking(m); table.remove(ForgeBellowsValveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeBellowsValveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeBellowsValveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeBellowsValveMaker.getStats() return {ironStock=ForgeBellowsValveMaker.ironStock,bronzeStock=ForgeBellowsValveMaker.bronzeStock,woodStock=ForgeBellowsValveMaker.woodStock,leatherStock=ForgeBellowsValveMaker.leatherStock,silverStock=ForgeBellowsValveMaker.silverStock,goldStock=ForgeBellowsValveMaker.goldStock,jewelStock=ForgeBellowsValveMaker.jewelStock,pearlStock=ForgeBellowsValveMaker.pearlStock,productStock=ForgeBellowsValveMaker.productStock,numBuildings=#ForgeBellowsValveMaker.buildings,hasMaker=ForgeBellowsValveMaker.maker~=nil,makerName=ForgeBellowsValveMaker.maker and ForgeBellowsValveMaker.maker.name or "—",makerSkill=ForgeBellowsValveMaker.maker and ForgeBellowsValveMaker.maker.skill or 0,activeMaking=#ForgeBellowsValveMaker.activeMaking,totalProducts=ForgeBellowsValveMaker.totalProducts} end
return ForgeBellowsValveMaker
